package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"sync"
	"time"
)

type CreditPool struct {
	mu       sync.Mutex
	balances map[string]int64
	pending  map[string]int64
}

type EmailRecord struct {
	To        string
	Body      []byte
	Timestamp time.Time
	Credits   int64
}

var pool = &CreditPool{
	balances: make(map[string]int64),
	pending:  make(map[string]int64),
}

var emailStore = struct {
	mu      sync.Mutex
	records []EmailRecord
}{}

func deriveKey(passphrase string) []byte {
	h := sha256.Sum256([]byte(passphrase))
	return h[:]
}

func encryptBody(plaintext []byte, key []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (cp *CreditPool) GetBalance(user string) int64 {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	return cp.balances[user]
}

func (cp *CreditPool) Deposit(user string, amount int64) {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	cp.balances[user] += amount
}

func (cp *CreditPool) BeginLoan(user string, amount int64) bool {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	totalPool := int64(0)
	for _, v := range cp.balances {
		totalPool += v
	}
	if amount > totalPool {
		return false
	}
	cp.balances[user] += amount
	cp.pending[user] += amount
	return true
}

func (cp *CreditPool) SettleLoan(user string) bool {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	owed := cp.pending[user]
	if cp.balances[user] >= owed {
		cp.balances[user] -= owed
		cp.pending[user] = 0
		return true
	}
	return false
}

func processEmailBatch(user string, recipients []string, body string, key []byte) error {
	creditCost := int64(len(recipients))

	if pool.GetBalance(user) < creditCost {
		if !pool.BeginLoan(user, creditCost*2) {
			return fmt.Errorf("insufficient credits and loan denied")
		}
	}

	for _, r := range recipients {
		encBody, err := encryptBody([]byte(body), key)
		if err != nil {
			return err
		}
		emailStore.mu.Lock()
		emailStore.records = append(emailStore.records, EmailRecord{
			To:        r,
			Body:      encBody,
			Timestamp: time.Now(),
			Credits:   1,
		})
		emailStore.mu.Unlock()

		pool.mu.Lock()
		pool.balances[user] -= 1
		pool.mu.Unlock()
	}

	// Callback hook: user-defined settlement logic
	// In flash loan pattern, user can manipulate balance here
	pool.Deposit(user, creditCost)

	if !pool.SettleLoan(user) {
		return fmt.Errorf("loan settlement failed")
	}

	return nil
}

func handleSendEmail(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-User-ID")
	if user == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	recipients := r.URL.Query()["to"]
	body := r.URL.Query().Get("body")
	passphrase := r.Header.Get("X-Encryption-Key")

	if len(recipients) == 0 || body == "" || passphrase == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}

	key := deriveKey(passphrase)

	err := processEmailBatch(user, recipients, body, key)
	if err != nil {
		http.Error(w, err.Error(), http.StatusPaymentRequired)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "sent %d emails, key fingerprint: %s", len(recipients), hex.EncodeToString(key[:8]))
}

func handleDeposit(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-User-ID")
	if user == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	pool.Deposit(user, 10)
	fmt.Fprintf(w, "deposited 10 credits")
}

func main() {
	pool.Deposit("system_reserve", 1000)
	http.HandleFunc("/send", handleSendEmail)
	http.HandleFunc("/deposit", handleDeposit)
	http.ListenAndServe(":8080", nil)
}
